1: package holdout
2: 
3: type sample struct{ at, value int }
4: type Window struct {
5: 	Width   int
6: 	samples []sample
7: 	last    int
8: 	started bool
9: }
10: 
11: func (w *Window) Add(now, value int) (int, bool) {
12: 	if w.started && now < w.last {
13: 		return 0, false
14: 	}
15: 	w.last = now
16: 	w.started = true
17: 	w.samples = append(w.samples, sample{now, value})
18: 	first := 0
19: 	for first < len(w.samples) && w.samples[first].at < now-w.Width {
20: 		first++
21: 	}
22: 	w.samples = w.samples[first:]
23: 	sum := 0
24: 	for _, s := range w.samples {
25: 		sum += s.value
26: 	}
27: 	return sum, true
28: }

file_sha256:c99d8dc8a4cc43946d69a9d21646900cde02df0e4239774337ea80c70aff4fb2
1: package holdout
2: 
3: import "testing"
4: 
5: func TestWindow(t *testing.T) {
6: 	w := Window{Width: 5}
7: 	for _, tc := range []struct{ at, value, want int }{{0, 3, 3}, {4, 2, 5}, {5, 7, 9}, {5, -2, 7}, {10, 1, 1}} {
8: 		got, ok := w.Add(tc.at, tc.value)
9: 		if !ok || got != tc.want {
10: 			t.Fatalf("at %d sum %d", tc.at, got)
11: 		}
12: 	}
13: 	if _, ok := w.Add(9, 100); ok {
14: 		t.Fatal("backdated sample accepted")
15: 	}
16: 	if got, ok := w.Add(10, 2); !ok || got != 3 {
17: 		t.Fatal(got, ok)
18: 	}
19: }

